@import "tailwindcss";

:root {
  --night: #140a2e;
  --fog: #000000;
  --pink: #ff4f8b;
  --orange: #ff8a3d;
  --gold: #ffc857;
  --purple: #7b2ff7;
  --teal: #2ee6d6;
  --ink: #f6efff;

  /* Safe areas: real insets on a phone, faked inside the laptop phone frame */
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

@theme inline {
  --color-night: var(--night);
  --color-fog: var(--fog);
  --color-pink: var(--pink);
  --color-orange: var(--orange);
  --color-gold: var(--gold);
  --color-purple: var(--purple);
  --color-teal: var(--teal);
  --color-ink: var(--ink);
  --font-display: var(--font-anton);
  --font-sans: var(--font-bricolage);
}

html,
body {
  height: 100%;
  background: var(--night);
  color: var(--ink);
  overscroll-behavior: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

body {
  font-family: var(--font-bricolage), system-ui, sans-serif;
  -webkit-font-smoothing: antialiased;
}

/* UI chrome shouldn't feel like a web page */
button,
nav,
header,
.ui-chrome {
  -webkit-touch-callout: none;
  user-select: none;
}

input,
textarea,
select {
  font-size: 16px; /* prevents iOS focus zoom */
  user-select: text;
}

/* ---------- Shell: full screen on phones, phone frame on wide screens ---------- */
.shell {
  height: 100dvh;
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.app-root {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--night);
  isolation: isolate;
}

@media (min-width: 768px) {
  .shell {
    background:
      radial-gradient(60% 50% at 20% 100%, rgb(255 79 139 / 0.35), transparent 70%),
      radial-gradient(50% 45% at 85% 90%, rgb(255 138 61 / 0.28), transparent 70%),
      radial-gradient(70% 60% at 50% 0%, rgb(123 47 247 / 0.35), transparent 70%),
      #0b0618;
  }

  .app-root {
    --safe-top: 47px;
    --safe-bottom: 21px;
    width: min(430px, calc((100dvh - 48px) * 430 / 932));
    height: auto;
    aspect-ratio: 430 / 932;
    border-radius: 56px;
    box-shadow:
      0 0 0 10px #05030b,
      0 0 0 12px rgb(255 255 255 / 0.08),
      0 40px 120px -20px rgb(255 79 139 / 0.45);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

