    lat <= CAMPUS_BBOX.north
  );
}

/** Scripted demo walk: UCC → UC Hill → Middlesex → Natural Science → Weldon → Thames bank. */
export const DEMO_WALK: LngLat[] = [
  [-81.2752, 43.0081],
  [-81.2744, 43.0086],
  [-81.2737, 43.0090],
  [-81.2726, 43.0092],
  [-81.2712, 43.0093],
  [-81.2703, 43.0100],
  [-81.2709, 43.0110],
  [-81.2722, 43.0118],
  [-81.2738, 43.0122],
  [-81.2755, 43.0116],
  [-81.2768, 43.0105],
  [-81.2781, 43.0094],
  [-81.2790, 43.0080],
  [-81.2786, 43.0064],
  [-81.2770, 43.0055],
];

/** Densify a path so consecutive points are at most `stepM` metres apart. */
export function densify(path: LngLat[], stepM = 20): LngLat[] {
  const out: LngLat[] = [];
  for (let i = 0; i < path.length - 1; i++) {
    const [a, b] = [path[i], path[i + 1]];
    const d = distanceM(a, b);
    const n = Math.max(1, Math.ceil(d / stepM));
    for (let k = 0; k < n; k++) {
      const t = k / n;
      out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);
    }
  }
  out.push(path[path.length - 1]);
  return out;
}

export function distanceM([lng1, lat1]: LngLat, [lng2, lat2]: LngLat) {
  const R = 6371000;
  const toRad = Math.PI / 180;
  const dLat = (lat2 - lat1) * toRad;
  const dLng = (lng2 - lng1) * toRad;
  const s =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(lat1 * toRad) * Math.cos(lat2 * toRad) * Math.sin(dLng / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}

/** Mapbox Standard configuration for the Forest State sunset look. */

export type LightPreset = "dawn" | "day" | "dusk" | "night";

/** Light preset from London, ON local time (fixed windows; suncalc-accurate timing is a later feature). */
export function londonLightPreset(now = new Date()): LightPreset {
  const hour = Number(
    new Intl.DateTimeFormat("en-CA", { hour: "numeric", hour12: false, timeZone: "America/Toronto" }).format(now),
  );
  if (hour >= 6 && hour < 8) return "dawn";
  if (hour >= 8 && hour < 16) return "day";
  if (hour >= 16 && hour < 19) return "dusk";
