        <p className="text-[13px] text-ink/85">{copy.text}</p>
        {copy.action && (
          <button
            type="button"
            onClick={startWatching}
            className="min-h-[36px] rounded-full bg-teal px-4 text-[13px] font-bold text-night"
          >
            {copy.action}
          </button>
        )}
      </div>
    </div>
  );
}

