    let i = 0;
    setWalking(true);
    timer.current = setInterval(() => {
      if (i >= path.length) return stopWalk();
      acceptFix(path[i]);
      if (i % 3 === 0) map.current?.follow(path[i]);
      i++;
    }, 160);
  };

  if (!open) return null;

  const btn = "w-full rounded-lg bg-white/10 px-3 py-2 text-left text-[13px] font-semibold text-white hover:bg-white/20";

  return createPortal(
    <div className="fixed top-4 left-4 z-[100] w-56 space-y-1.5 rounded-xl border border-white/10 bg-black/85 p-3 font-sans shadow-2xl">
      <p className="pb-1 text-[11px] font-bold tracking-[0.2em] text-pink uppercase">Demo controls</p>
      <button className={btn} onClick={walk}>{walking ? "■ Stop walk" : "▶ Walk campus"}</button>
      <button
        className={btn}
        onClick={() => {
          const c = map.current?.center();
          if (c) revealAt(c[1], c[0]);
        }}
      >
        Reveal here
      </button>
      <button className={btn} onClick={() => map.current?.flyToCampus()}>Fly to Mustang City</button>
      <button className={btn} onClick={() => map.current?.flyToCity()}>Fly to Forest State</button>
      <button className={btn} onClick={() => { stopWalk(); resetFog(); }}>Reset fog</button>
      <p className="pt-1 text-[11px] text-white/50">Press D to hide</p>
    </div>,
    document.body,
  );
}

"use client";

import { useEffect, useState } from "react";

type User = { name?: string; email?: string; picture?: string };
type State =
  | { kind: "loading" }
  | { kind: "signed-in"; user: User }
  | { kind: "signed-out" }
  | { kind: "unavailable" };

export default function ProfilePanel({ denied }: { denied: boolean }) {
  const [state, setState] = useState<State>({ kind: "loading" });

  useEffect(() => {
    let alive = true;
    fetch("/auth/profile", { cache: "no-store" })
      .then(async (res) => {
        if (!alive) return;
        if (res.ok && res.status !== 204) setState({ kind: "signed-in", user: await res.json() });
        else if (res.status === 401 || res.status === 204) setState({ kind: "signed-out" });
        else setState({ kind: "unavailable" });
      })
      .catch(() => alive && setState({ kind: "unavailable" }));
    return () => {
      alive = false;
    };
  }, []);

  const cta = "flex min-h-[52px] w-full items-center justify-center rounded-2xl text-[16px] font-bold uppercase tracking-wide";

  return (
    <div className="space-y-4 pb-4">
      {denied && (
        <p className="rounded-2xl border border-pink/40 bg-pink/10 px-4 py-3 text-[14px] text-ink">
          Only <b>@uwo.ca</b> accounts can sign in to Mustang City.
        </p>
      )}

      {state.kind === "loading" && <div className="h-24 animate-pulse rounded-2xl bg-white/5" />}

      {state.kind === "signed-in" && (
        <>
          <div className="flex items-center gap-4">
            {state.user.picture ? (
              // eslint-disable-next-line @next/next/no-img-element
              <img src={state.user.picture} alt="" className="h-14 w-14 rounded-full ring-2 ring-pink" />
            ) : (
              <div className="h-14 w-14 rounded-full bg-gradient-to-br from-pink to-orange" />
            )}
            <div className="min-w-0">
              <p className="truncate text-[18px] font-bold text-ink">{state.user.name ?? "Mustang"}</p>
              <p className="truncate text-[14px] text-ink/60">{state.user.email}</p>
            </div>
          </div>
          <a href="/auth/logout" className={`${cta} bg-white/10 text-ink`}>
            Sign out
          </a>
        </>
      )}

      {state.kind === "signed-out" && (
        <>
          <p className="text-[15px] leading-snug text-ink/80">
            Sign in with your Western account to save your map, earn Rep and join your faculty&apos;s turf war.
          </p>
          <a href="/auth/login" className={`${cta} bg-pink text-night shadow-[0_10px_40px_-8px_rgba(255,79,139,0.9)]`}>
            Sign in with @uwo.ca
          </a>
        </>
      )}

      {state.kind === "unavailable" && (
        <p className="text-[15px] text-ink/70">Sign-in isn&apos;t available on this deployment yet. Your fog map is saved on this device.</p>
      )}
    </div>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import MapView, { type MapHandle } from "./map/MapView";
import LoadingScreen from "./map/LoadingScreen";
import Hud from "./Hud";
import TabBar, { type Tab } from "./TabBar";
import Sheet from "./Sheet";
import LocationPrompt from "./LocationPrompt";
import ProfilePanel from "./ProfilePanel";
import DemoPanel from "./DemoPanel";

const TITLES: Record<Exclude<Tab, "map">, string> = { missions: "Missions", crew: "Crew", profile: "Profile" };

export default function GameScreen() {
  const map = useRef<MapHandle | null>(null);
  const [mapState, setMapState] = useState<"loading" | "ready" | "unavailable">("loading");
  const [reason, setReason] = useState<string>();
  const [tab, setTab] = useState<Tab>("map");
  const [denied, setDenied] = useState(false);

  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if (params.get("denied") === "uwo") {
      setDenied(true);
      setTab("profile");
      window.history.replaceState(null, "", "/");
    }
  }, []);

  return (
    <main className="absolute inset-0">
      <MapView
        ref={map}
        onReady={() => setMapState("ready")}
        onUnavailable={(r) => {
          setReason(r);
          setMapState("unavailable");
        }}
      />
      <Hud />
      {mapState === "ready" && <LocationPrompt />}

      <Sheet open={tab !== "map"} title={tab === "map" ? "" : TITLES[tab]} onClose={() => setTab("map")}>
        {tab === "profile" ? (
          <ProfilePanel denied={denied} />
        ) : (
          <p className="pb-4 text-[15px] text-ink/70">
            {tab === "missions"
              ? "The Goose is lining up jobs across Forest State. Missions drop tomorrow."
              : "Crews and friends are coming soon."}
          </p>
        )}
      </Sheet>

      <TabBar active={tab} onChange={setTab} />
      <LoadingScreen state={mapState} reason={reason} />
      <DemoPanel map={map} />
    </main>
  );
}

import GameScreen from "@/components/GameScreen";

export default function Home() {
  return <GameScreen />;
}

