  map.addLayer({
    id: "campus-labels",
    type: "symbol",
    source: "campus-labels",
    slot: "top",
    minzoom: 15,
    layout: {
      "text-field": ["get", "name"],
      "text-font": ["DIN Pro Bold", "Arial Unicode MS Bold"],
      "text-size": ["interpolate", ["linear"], ["zoom"], 15, 10, 18, 15],
      "text-transform": "uppercase",
      "text-letter-spacing": 0.06,
      "text-max-width": 8,
      "text-padding": 4,
